import{M as e,O as t,d as n,h as r,p as i}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as a}from"./app-fxBgVz1h.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/PostgreSQL/02_%E8%BF%9B%E9%98%B6%E7%AF%87/04_%E6%89%A9%E5%B1%95%E7%94%9F%E6%80%81.html","title":"扩展生态","lang":"zh-CN","frontmatter":{"title":"扩展生态","order":4,"category":["数据库","PostgreSQL"],"tag":["PostgreSQL","扩展","PostGIS","pgvector","pg_stat_statements"]},"git":{"createdTime":1780573763000,"updatedTime":1780712648000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":7.74,"words":2323},"filePathRelative":"后端开发/数据库/PostgreSQL/02_进阶篇/04_扩展生态.md"}`),s={name:`04_扩展生态.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="扩展生态" tabindex="-1"><a class="header-anchor" href="#扩展生态"><span>扩展生态</span></a></h1><div class="hint-container tip"><p class="hint-container-title">核心观点</p><p>PostgreSQL 的扩展系统是它区别于其他数据库的最大优势——从地理空间到 AI 向量搜索，从模糊匹配到定时任务，几乎任何功能都可以通过扩展加入。理解扩展生态，就是在理解 PG 的能力边界。</p></div><h2 id="扩展系统概述" tabindex="-1"><a class="header-anchor" href="#扩展系统概述"><span>扩展系统概述</span></a></h2>`,3),r(d,{code:``}),o[1]||=i(`<h3 id="扩展管理" tabindex="-1"><a class="header-anchor" href="#扩展管理"><span>扩展管理</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看已安装的扩展</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> extname, extversion </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_extension;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看可用的扩展</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, default_version, installed_version, comment</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_available_extensions</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装扩展</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> extension_name;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装到指定 schema</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> extension_name </span><span style="color:#C678DD;">SCHEMA</span><span style="color:#ABB2BF;"> my_schema;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 卸载扩展</span></span>
<span class="line"><span style="color:#C678DD;">DROP</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> extension_name;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 更新扩展</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#ABB2BF;"> EXTENSION extension_name </span><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">扩展安装前提</p><ul><li>扩展的 <code>.control</code> 文件和 <code>.so</code>/<code>.dll</code> 文件必须已在系统中</li><li>在 Docker/云环境中，需要使用包含扩展的镜像</li><li>Supabase 预装了大量常用扩展，开箱即用</li><li>参考文档：<a href="https://www.postgresql.org/docs/16/extend-extensions.html" target="_blank" rel="noopener noreferrer">Extension Infrastructure</a></li></ul></div><h2 id="postgis" tabindex="-1"><a class="header-anchor" href="#postgis"><span>PostGIS</span></a></h2><p>PostGIS 是 PostgreSQL 最流行的扩展，将 PG 变成功能完整的空间数据库：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> postgis;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 验证</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> PostGIS_Full_Version();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建空间表</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> stores</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id        </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;">      text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    category  </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#C678DD;">  geometry</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Point</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,  </span><span style="color:#7F848E;font-style:italic;">-- WGS84 坐标系</span></span>
<span class="line"><span style="color:#ABB2BF;">    area      </span><span style="color:#C678DD;">geometry</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Polygon</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 插入空间数据（经度 纬度）</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> stores (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, category, </span><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;星巴克国贸店&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;咖啡&#39;</span><span style="color:#ABB2BF;">, ST_SetSRID(ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4614</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9092</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">)),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;瑞幸望京店&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;咖啡&#39;</span><span style="color:#ABB2BF;">, ST_SetSRID(ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4802</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9941</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">)),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;全家便利店&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;零售&#39;</span><span style="color:#ABB2BF;">, ST_SetSRID(ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4551</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9115</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">));</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- GiST 索引（空间查询必需）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_stores_location</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> stores </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GiST (</span><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 附近搜索（5km 内的咖啡店）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">       ST_Distance(</span><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">, ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">46</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">91</span><span style="color:#ABB2BF;">)::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> dist_meters</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> stores</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> category </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;咖啡&#39;</span></span>
<span class="line"><span style="color:#C678DD;">  AND</span><span style="color:#ABB2BF;"> ST_DWithin(</span><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">, ST_MakePoint(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">46</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">91</span><span style="color:#ABB2BF;">)::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">5000</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> dist_meters;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 范围查询（某区域内）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> stores</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> ST_Contains(</span></span>
<span class="line"><span style="color:#ABB2BF;">    ST_MakeEnvelope(</span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">45</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">90</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">47</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">92</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#C678DD;">    location</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 计算面积</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, ST_Area(area::</span><span style="color:#C678DD;">geography</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> area_sqm </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> regions;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">PostGIS vs 专用 GIS 数据库</p><p>PostGIS 提供了 OGC 标准的完整空间功能，包括：</p><ul><li>空间索引（GiST/SP-GiST）</li><li>空间函数（距离、面积、相交、缓冲区）</li><li>栅格数据（postgis_raster）</li><li>拓扑分析（postgis_topology）</li><li>地理编码（postgis_tiger_geocoder）</li></ul><p>多数场景下 PostGIS 可以替代专用 GIS 系统。</p></div><h2 id="pg-trgm" tabindex="-1"><a class="header-anchor" href="#pg-trgm"><span>pg_trgm</span></a></h2><p>pg_trgm（Trigram）提供基于三元组的模糊搜索和相似度匹配：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> pg_trgm;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 三元组原理：将字符串拆分为连续三个字符的子串</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- &quot;PostgreSQL&quot; → &quot;  p&quot;, &quot; po&quot;, &quot;pos&quot;, &quot;ost&quot;, &quot;stg&quot;, &quot;tgr&quot;, &quot;gre&quot;, &quot;res&quot;, &quot;esq&quot;, &quot;sql&quot;, &quot;ql &quot;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 模糊匹配基于三元组的重叠度</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> contacts</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id   </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;"> text</span><span style="color:#C678DD;"> NOT NULL</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> contacts (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;张三丰&#39;</span><span style="color:#ABB2BF;">), (</span><span style="color:#98C379;">&#39;张三&#39;</span><span style="color:#ABB2BF;">), (</span><span style="color:#98C379;">&#39;张山&#39;</span><span style="color:#ABB2BF;">), (</span><span style="color:#98C379;">&#39;李四&#39;</span><span style="color:#ABB2BF;">), (</span><span style="color:#98C379;">&#39;王五&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 模糊搜索</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, similarity(</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;张三&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> sim</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> contacts</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;"> % </span><span style="color:#98C379;">&#39;张三&#39;</span><span style="color:#7F848E;font-style:italic;">        -- % = 相似度超过阈值</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> sim </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  name  | sim</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- -------+-----</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  张三   | 1.0</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  张三丰 | 0.5</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  张山   | 0.5</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 调整相似度阈值</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW </span><span style="color:#D19A66;">pg_trgm</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">similarity_threshold</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 默认 0.3</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> pg_trgm</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">similarity_threshold</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- GIN 索引加速模糊搜索</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_contacts_name_trgm</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> contacts </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> GIN (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;"> gin_trgm_ops);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- LIKE 优化（中缀/后缀匹配也能用索引）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> contacts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;%三%&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 可以用 GIN pg_trgm 索引！B-Tree 做不到</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="pg-stat-statements" tabindex="-1"><a class="header-anchor" href="#pg-stat-statements"><span>pg_stat_statements</span></a></h2><p>pg_stat_statements 是 PG 最重要的性能监控扩展：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装（需要修改 shared_preload_libraries）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- postgresql.conf:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- shared_preload_libraries = &#39;pg_stat_statements&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pg_stat_statements.track = all</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> pg_stat_statements;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 最慢的 10 条查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query,</span></span>
<span class="line"><span style="color:#ABB2BF;">       calls,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(total_exec_time::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> total_ms,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(mean_exec_time::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> avg_ms,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(max_exec_time::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> max_ms,</span></span>
<span class="line"><span style="color:#C678DD;">       rows</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">((</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> * shared_blks_hit::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> /</span></span>
<span class="line"><span style="color:#56B6C2;">              nullif</span><span style="color:#ABB2BF;">(shared_blks_hit + shared_blks_read, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">))::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> cache_hit_pct</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> total_exec_time </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询次数最多</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query, calls, </span><span style="color:#56B6C2;">round</span><span style="color:#ABB2BF;">(mean_exec_time::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> avg_ms</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> calls </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- IO 最重</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query, shared_blks_read + local_blks_read </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> total_blks_read</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> shared_blks_read + local_blks_read </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 重置统计</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_stat_statements_reset();</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="pg-cron" tabindex="-1"><a class="header-anchor" href="#pg-cron"><span>pg_cron</span></a></h2><p>pg_cron 在数据库内运行定时任务，无需外部调度器：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装（需要 shared_preload_libraries）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> pg_cron;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每天凌晨 2 点清理过期数据</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> cron</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">schedule</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#98C379;">    &#39;cleanup-expired&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    &#39;0 2 * * *&#39;</span><span style="color:#ABB2BF;">,       </span><span style="color:#7F848E;font-style:italic;">-- cron 表达式</span></span>
<span class="line"><span style="color:#ABB2BF;">    $$</span><span style="color:#C678DD;">DELETE</span><span style="color:#C678DD;"> FROM</span><span style="color:#C678DD;"> sessions</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> expires_at </span><span style="color:#56B6C2;">&lt;</span><span style="color:#C678DD;"> now</span><span style="color:#ABB2BF;">()$$</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每小时更新统计</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> cron</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">schedule</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#98C379;">    &#39;update-stats&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    &#39;0 * * * *&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    $$ANALYZE orders$$</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每周一凌晨 3 点生成分区</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> cron</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">schedule</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#98C379;">    &#39;create-weekly-partition&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    &#39;0 3 * * 1&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    $$</span></span>
<span class="line"><span style="color:#C678DD;">    CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> orders_2025_w24</span><span style="color:#C678DD;"> PARTITION</span><span style="color:#ABB2BF;"> OF orders</span></span>
<span class="line"><span style="color:#C678DD;">        FOR</span><span style="color:#C678DD;"> VALUES</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;2025-06-09&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;2025-06-16&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">    $$</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看已调度的任务</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> cron</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">job</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 取消任务</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> cron</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">unschedule</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;cleanup-expired&#39;</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="pgaudit" tabindex="-1"><a class="header-anchor" href="#pgaudit"><span>pgAudit</span></a></h2><p>pgAudit 提供详细的审计日志，满足合规要求：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装（需要 shared_preload_libraries）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- postgresql.conf:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- shared_preload_libraries = &#39;pgaudit&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pgaudit.log = &#39;all&#39;             -- 记录所有操作</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pgaudit.log_catalog = off       -- 不记录系统目录操作</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 按会话级别控制审计</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> pgaudit</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">log</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;write&#39;</span><span style="color:#ABB2BF;">;         </span><span style="color:#7F848E;font-style:italic;">-- 审计写操作 (INSERT/UPDATE/DELETE)</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> pgaudit</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">log</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;read,write&#39;</span><span style="color:#ABB2BF;">;    </span><span style="color:#7F848E;font-style:italic;">-- 审计读写</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> pgaudit</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">log</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;ddl&#39;</span><span style="color:#ABB2BF;">;           </span><span style="color:#7F848E;font-style:italic;">-- 审计 DDL</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> pgaudit</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">log</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;role&#39;</span><span style="color:#ABB2BF;">;          </span><span style="color:#7F848E;font-style:italic;">-- 审计角色操作</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 审计日志写入 PG 日志文件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2025-06-04 10:30:00 UTC [12345]: [5-1] AUDIT: SESSION,1,1,WRITE,INSERT,,,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   INSERT INTO accounts (name, balance) VALUES (&#39;Alice&#39;, 1000);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">pgAudit vs PG 原生日志</p><ul><li>PG 原生日志（<code>log_statement = &#39;all&#39;</code>）：记录所有 SQL，但无结构化字段</li><li>pgAudit：结构化日志，包含操作类型、对象、角色等字段</li><li>合规场景（金融、医疗）必须用 pgAudit</li></ul></div><h2 id="pgvector" tabindex="-1"><a class="header-anchor" href="#pgvector"><span>pgvector</span></a></h2><p>pgvector 为 PG 添加向量相似度搜索，是 AI 应用的核心扩展：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#C678DD;"> vector</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建带向量列的表</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> documents</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    content    </span><span style="color:#C678DD;">text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    embedding  </span><span style="color:#C678DD;">vector</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1536</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#7F848E;font-style:italic;">  -- OpenAI text-embedding-ada-002 维度</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 插入向量</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> documents (content, embedding) </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;PostgreSQL is the most advanced open source database&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">     &#39;[0.1, 0.2, 0.3, ...]&#39;</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">vector</span><span style="color:#ABB2BF;">),  </span><span style="color:#7F848E;font-style:italic;">-- 实际是 1536 维</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;MySQL is a popular relational database&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">     &#39;[0.15, 0.25, 0.28, ...]&#39;</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">vector</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 向量相似度搜索（余弦距离）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> content, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> - (embedding </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#98C379;"> &#39;[0.12, 0.22, 0.31, ...]&#39;</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">vector</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> similarity</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> documents</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> embedding </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#98C379;"> &#39;[0.12, 0.22, 0.31, ...]&#39;</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">vector</span><span style="color:#7F848E;font-style:italic;">  -- &lt;=&gt; = 余弦距离</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 索引类型</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- HNSW（PG 15+，推荐）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_documents_embedding_hnsw</span></span>
<span class="line"><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> documents </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> hnsw (embedding vector_cosine_ops);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- IVFFlat（PG 13+）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_documents_embedding_ivfflat</span></span>
<span class="line"><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> documents </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> ivfflat (embedding vector_cosine_ops)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> (lists </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>索引类型</th><th>构建速度</th><th>查询速度</th><th>召回率</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>HNSW</strong></td><td>慢</td><td>快</td><td>高</td><td>推荐默认选择</td></tr><tr><td><strong>IVFFlat</strong></td><td>快</td><td>中</td><td>中</td><td>数据频繁变更</td></tr></tbody></table><h2 id="hypopg" tabindex="-1"><a class="header-anchor" href="#hypopg"><span>HypoPG</span></a></h2><p>HypoPG 创建虚拟索引来测试索引效果，不消耗实际资源：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> hypopg;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前查询计划</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Seq Scan on orders</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建虚拟索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> hypopg_create_index(</span><span style="color:#98C379;">&#39;CREATE INDEX idx_orders_user_id ON orders (user_id)&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看虚拟索引是否改变计划</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN </span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Scan using idx_orders_user_id on orders  ← 可以用索引！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看所有虚拟索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> hypopg();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 估算虚拟索引大小</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> indexname, hypopg_estimate_size(indexrelid) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> est_bytes</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> hypopg();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 删除所有虚拟索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> hypopg_reset();</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">HypoPG 的使用场景</p><ul><li><strong>评估索引价值</strong>：先创建虚拟索引，看执行计划是否改善</li><li><strong>避免盲目建索引</strong>：建大表索引耗时很长，先验证再执行</li><li>参考文档：<a href="https://hypopg.readthedocs.io/" target="_blank" rel="noopener noreferrer">HypoPG</a></li></ul></div><h2 id="citus" tabindex="-1"><a class="header-anchor" href="#citus"><span>Citus</span></a></h2><p>Citus 将 PG 扩展为分布式数据库，适合大规模数据处理：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 安装</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION </span><span style="color:#C678DD;">IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> citus;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 选择分布列</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> create_distributed_table(</span><span style="color:#98C379;">&#39;orders&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;user_id&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Citus 自动将数据按 user_id 哈希分布到多个节点</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 协调节点自动路由查询到正确的分片</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 共置表（colocation）：相同分布键的表 JOIN 在本地执行</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> create_distributed_table(</span><span style="color:#98C379;">&#39;order_items&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;order_id&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    colocate_with </span><span style="color:#56B6C2;">=&gt;</span><span style="color:#98C379;"> &#39;orders&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 引用表（小表广播到所有节点）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> create_reference_table(</span><span style="color:#98C379;">&#39;products&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 分布式查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> u</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">name</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">amount</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> total</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users u</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> orders o </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> u</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">user_id</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#D19A66;"> u</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">name</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 自动下推到各分片执行，汇总结果</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="自定义扩展" tabindex="-1"><a class="header-anchor" href="#自定义扩展"><span>自定义扩展</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- PG 扩展的最小结构：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 扩展控制文件 (my_ext.control)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. SQL 脚本 (my_ext--1.0.sql)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. C 代码 (my_ext.c)（如果需要自定义函数）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- my_ext.control</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- comment = &#39;My custom extension&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- default_version = &#39;1.0&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- module_pathname = &#39;$libdir/my_ext&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- relocatable = true</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- my_ext--1.0.sql</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- CREATE FUNCTION my_function(text) RETURNS text</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--     AS &#39;my_ext&#39;, &#39;my_function&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--     LANGUAGE C STRICT;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 编译安装后</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION my_ext;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="supabase-预装扩展" tabindex="-1"><a class="header-anchor" href="#supabase-预装扩展"><span>Supabase 预装扩展</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看 Supabase 预装的扩展</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, default_version, comment</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_available_extensions</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> installed_version </span><span style="color:#C678DD;">IS NOT NULL</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 常用预装扩展：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pgcrypto    - 加密函数</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pgjwt       - JWT 编解码</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- uuid-ossp   - UUID 生成</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pg_stat_statements - 查询监控</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pg_trgm     - 模糊搜索</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- plpgsql     - 存储过程语言</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- postgis     - 地理空间</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- pg_cron     - 定时任务</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- vector      - 向量搜索</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- supabase_vault - 密钥管理</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>PG 的扩展系统有什么优势？</strong></p><ul><li>可插拔：按需加载，不影响核心</li><li>标准 API：CREATE EXTENSION 统一管理</li><li>C 函数：可以访问 PG 内部 API，高性能</li><li>社区丰富：数百个高质量扩展</li></ul></li><li><p><strong>PostGIS 适合什么场景？</strong></p><ul><li>LBS 应用（附近的人/店）</li><li>地理围栏</li><li>路径规划</li><li>空间分析（面积、距离、相交）</li></ul></li><li><p><strong>pgvector 和专用向量数据库（如 Milvus）的区别？</strong></p><ul><li>pgvector：PG 生态，事务+JOIN+向量一体化</li><li>Milvus：纯向量，性能更高，但无事务</li><li>小规模（百万级）→ pgvector 足够</li><li>大规模（亿级）→ 专用向量数据库</li></ul></li><li><p><strong>pg_stat_statements 怎么用？</strong></p><ul><li>需要在 <code>shared_preload_libraries</code> 中加载</li><li>按 total_exec_time 找最慢查询</li><li>按 calls 找高频查询</li><li>按 shared_blks_read 找 IO 重查询</li></ul></li><li><p><strong>HypoPG 解决什么问题？</strong></p><ul><li>大表建索引耗时太长，不敢盲建</li><li>先用 HypoPG 虚拟索引验证执行计划</li><li>确认有用再真正创建</li></ul></li></ol></div><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://www.postgresql.org/docs/16/extend-extensions.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Extensions</a></li><li><a href="https://postgis.net/documentation/" target="_blank" rel="noopener noreferrer">PostGIS 官方文档</a></li><li><a href="https://github.com/pgvector/pgvector" target="_blank" rel="noopener noreferrer">pgvector GitHub</a></li><li><a href="https://www.postgresql.org/docs/16/pgstatstatements.html" target="_blank" rel="noopener noreferrer">pg_stat_statements</a></li><li><a href="https://hypopg.readthedocs.io/" target="_blank" rel="noopener noreferrer">HypoPG</a></li><li><a href="https://github.com/citusdata/citus" target="_blank" rel="noopener noreferrer">Citus GitHub</a></li><li><a href="https://github.com/supabase/supabase" target="_blank" rel="noopener noreferrer">Supabase Extensions</a></li></ul>`,40)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};